/**
 * Single source of truth for the portfolio.
 * Add or edit a project here — the boarding passes, the departures board
 * and the globe all read from this file.
 *
 * Media lives in /public/media/<id>/ and is generated by `npm run capture`.
 */

export type StopId = 'AR' | 'CL' | 'US' | 'AE'

export interface Stop {
  id: StopId
  country: string
  /** Short name for the passport stamp */
  stamp: string
  city: string
  /** IATA city / airport code shown on the boarding pass */
  code: string
  lat: number
  lng: number
  timeZone: string
}

export interface Project {
  id: string
  /** Shown as the flight number: FD 001, FD 002... */
  number: number
  name: string
  url: string
  stop: StopId
  /** "Gate" on the boarding pass */
  platform: string
  /** "Class" on the boarding pass */
  industry: string
  summary: string
  builtAtBeing: boolean
  featured: boolean
  /** Slug of the case study page, if it has one */
  caseStudy?: string
}

