export const flightNumber = (p: Project) => `FD ${String(p.number).padStart(3, '0')}`
export const stopById = (id: StopId) => stops.find((s) => s.id === id)!
export const projectsAt = (id: StopId) => projects.filter((p) => p.stop === id)
export const projectById = (id: string) => projects.find((p) => p.id === id)!
export const caseUrl = (p: Project) => (p.caseStudy ? `/cases/${p.caseStudy}.html` : undefined)
export const mediaPath = (p: Project, file: 'desktop.webp' | 'mobile.webp' | 'scroll.mp4' | 'full.webp') =>
  `/media/${p.id}/${file}`
